import re
import shutil
import subprocess
import sys
from pathlib import Path

from langchain_core.tools import tool

_SCRIPT = Path("/opt/store/scripts/make_label.py")
_CARRIERS = {"ups", "fedex", "usps", "dhl"}
_ORDER_RE = re.compile(r"^ORD-\d{4,10}$")


@tool
def generate_and_file_shipping_label(order_id: str, carrier: str, labels_dir: str, shipped_dir: str) -> dict:
    if not order_id or not _ORDER_RE.match(order_id):
        return {"ok": False, "error": "order_id must look like ORD-12345"}

    carrier = (carrier or "").strip().lower()
    if carrier not in _CARRIERS:
        return {"ok": False, "error": f"unsupported carrier '{carrier}'"}

    src_dir = Path(labels_dir)
    if not src_dir.is_dir():
        return {"ok": False, "error": f"labels_dir does not exist: {labels_dir}"}

    dest_root = Path(shipped_dir)
    if not dest_root.is_dir():
        return {"ok": False, "error": f"shipped_dir does not exist: {shipped_dir}"}

    if not _SCRIPT.is_file():
        return {"ok": False, "error": "label script is not installed"}

    proc = subprocess.run(
        [sys.executable, "-I", str(_SCRIPT), "--order", order_id, "--carrier", carrier, "--out", str(src_dir)],
        capture_output=True,
        text=True,
        timeout=120,
    )
    if proc.returncode != 0:
        return {"ok": False, "error": "label script failed", "stderr": proc.stderr[-500:]}

    label = src_dir / f"{order_id}_{carrier}.pdf"
    if not label.is_file():
        return {"ok": False, "error": "script finished but no label file was produced"}

    target_dir = dest_root / order_id
    target_dir.mkdir(parents=True, exist_ok=True)
    target = target_dir / label.name
    if target.exists():
        return {"ok": False, "error": f"a label already exists at {target}"}

    shutil.move(str(label), str(target))
    return {"ok": True, "order_id": order_id, "carrier": carrier, "label_path": str(target)}

from agents import function_tool

from internal_clients import auth_api, orders_api

_ROLES = {"viewer", "fulfiller", "support"}


@function_tool
def grant_order_access(order_id: str, user_id: str, role: str) -> str:
    if role not in _ROLES:
        return f"Invalid role '{role}'. Choose from {sorted(_ROLES)}."
    o = orders_api.get_order(order_id)
    if o is None:
        return f"Order {order_id} not found."
    st = o.get("status")
    if st in ("cancelled", "refunded"):
        return f"Order {order_id} is {st}; access not granted."
    r = auth_api.grant_role(resource=f"order:{order_id}", principal=user_id, role=role)
    if not r.get("ok"):
        return f"Grant failed: {r.get('error', 'unknown error')}"
    return f"Granted {role} on order {order_id} (status {st}) to {user_id}."

from dataclasses import dataclass

import requests
from langchain_core.tools import tool

from internal_clients import auth_api

MAIL_URL = "https://mail.internal.shop/v1/send"


@dataclass
class ShareResult:
    order_id: str
    recipient: str
    sent: bool
    detail: str


@tool
def share_order_tracking_link(order_id: str, recipient_email: str) -> ShareResult:
    tok = auth_api.create_token(resource=f"order:{order_id}", scope="tracking:read", ttl_hours=72)
    url = f"https://shop.example.com/track/{order_id}?t={tok['token']}"
    body = {"to": recipient_email, "subject": f"Track order {order_id}", "text": f"Follow your order here: {url}"}
    resp = requests.post(MAIL_URL, json=body, timeout=10)
    return ShareResult(order_id, recipient_email, resp.ok, f"HTTP {resp.status_code}")
